#include <array>
#include <iostream>

int main() {
    std::array<int, 4> scores = {70, 85, 90, 60};
    std::cout << "Size: " << scores.size() << '\n';
    std::cout << "Front: " << scores.front() << '\n';
    std::cout << "Back: " << scores.back() << '\n';
    std::cout << "At 2: " << scores.at(2) << '\n';

    const std::array<int, 4> backup = scores;
    scores[0] = 100;
    std::cout << "scores front: " << scores.front() << '\n';
    std::cout << "backup front: " << backup.front() << '\n';
    std::cout << std::boolalpha << "Equal: " << (scores == backup) << '\n';
    return 0;
}

