#include <array>
#include <iomanip>
#include <iostream>

int main() {
    std::cout << std::fixed << std::setprecision(1);
    std::array<double, 3> temps = {21.5, 19.0, 23.5};
    std::cout << "Size: " << temps.size() << '\n';
    std::cout << "Front: " << temps.front() << '\n';
    std::cout << "Back: " << temps.back() << '\n';
    std::cout << "At 1: " << temps.at(1) << '\n';

    std::array<double, 3> cleared = temps;
    cleared.fill(0.0);
    std::cout << "temps front: " << temps.front() << '\n';
    std::cout << "cleared front: " << cleared.front() << '\n';
    std::cout << std::boolalpha << "Equal: " << (temps == cleared) << '\n';
    return 0;
}

