#include <iostream>
#include <string>
#include <vector>

int main() {
    std::vector<std::string> tasks = {"Buy milk", "Write report"};
    tasks.push_back("Call Sam");
    std::cout << "Size: " << tasks.size() << '\n';
    std::cout << "Last: " << tasks.back() << '\n';
    std::cout << "tasks[0]: " << tasks[0] << '\n';
    std::cout << "tasks.at(1): " << tasks.at(1) << '\n';

    tasks.pop_back();
    std::cout << "Size: " << tasks.size() << '\n';
    std::cout << "First: " << tasks.front() << '\n';

    tasks.clear();
    std::cout << std::boolalpha << "Empty: " << tasks.empty() << '\n';
    return 0;
}

